#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import csv
import gzip
import io
import json
import sys
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from pathlib import Path
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    data = Path(path).read_bytes()
    while data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    text = data.decode("utf-8-sig")
    return text


def lines_of(text):
    return [l for l in text.replace("\r\n", "\n").replace("\r", "\n").split("\n") if l.strip() != ""]


def read_csv_rows(path):
    with open(path, newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def from_epoch(sec):
    return EPOCH + timedelta(seconds=sec)


def local_to_instant(naive, zone, abbr_dst=None):
    """naive local datetime -> aware UTC datetime.
    abbr_dst: True/False/None selects occurrence when ambiguous (None -> first)."""
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() != b.utcoffset():
        # either ambiguous or a gap
        ua = a.astimezone(UTC)
        ub = b.astimezone(UTC)
        # ambiguous: fold=0 is earlier instant (the DST one)
        if ua < ub or True:
            if abbr_dst is False:
                return b.astimezone(UTC)
            return a.astimezone(UTC)
    return a.astimezone(UTC)


def std_offset(zone, around):
    """Standard UTC offset of the zone near the given UTC datetime."""
    best = None
    for dd in (0, 90, 180, 270, -90, -180, -270):
        t = (around + timedelta(days=dd)).astimezone(zone)
        off = t.utcoffset() - (t.dst() or timedelta(0))
        best = off if best is None else min(best, off)
        if not t.dst():
            return t.utcoffset()
    return best


# ---------------------------------------------------------------- parsers
# each returns list of (punch_id, employee, direction, instant)

def parse_abbr_csv(text, zone):
    out = []
    header = None
    for line in csv.reader(io.StringIO("\n".join(lines_of(text)))):
        if not line:
            continue
        cells = [c.strip() for c in line]
        if "Badge" in cells and "Record" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = r["Time"].upper().split()
        hms = t[0].split(":")
        h, m, s = int(hms[0]), int(hms[1]), int(hms[2])
        if len(t) > 1:
            ap = t[1]
            h = h % 12
            if ap == "PM":
                h += 12
        naive = d.replace(hour=h, minute=m, second=s)
        ab = r.get("Zone", "").upper()
        dst = True if ab.endswith("DT") else (False if ab.endswith("ST") else None)
        out.append((r["Record"], r["Badge"], r["Punch"].strip().upper(),
                    local_to_instant(naive, zone, dst)))
    return out


def parse_epoch_jsonl(text, zone):
    out = []
    schema = 1
    for line in lines_of(text):
        o = json.loads(line)
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            pid, emp, dr = o["punch_id"], o["employee"], o["direction"]
            inst = from_epoch(int(o["epoch_ms"]) // 1000)
        else:
            pid, emp, dr = o["id"], o["emp"], o["dir"]
            if "ts_ms" in o:
                inst = from_epoch(int(o["ts_ms"]) // 1000)
            else:
                inst = from_epoch(int(o["ts"]))
        out.append((str(pid), str(emp).strip(), str(dr).strip().upper(), inst))
    return out


def parse_offset_csv(text, zone):
    out = []
    header = None
    for row in csv.reader(io.StringIO("\n".join(lines_of(text))), delimiter=";"):
        cells = [c.strip() for c in row]
        if "punch_id" in cells and "timestamp" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        ev = r["event"].lower()
        dr = "IN" if ev.endswith("in") else "OUT"
        inst = datetime.fromisoformat(r["timestamp"]).astimezone(UTC)
        inst = inst.replace(microsecond=0)
        out.append((r["punch_id"], r["employee"], dr, inst))
    return out


def parse_legacy(text, zone):
    out = []
    default = None
    cur = None
    for line in lines_of(text):
        k = line[0]
        if k == "H":
            off = line[13:18].strip()
            if off:
                sign = -1 if off[0] == "-" else 1
                cur = sign * timedelta(hours=int(off[1:3]), minutes=int(off[3:5]))
            else:
                cur = None
        elif k == "D":
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = "IN" if line[15] == "I" else "OUT"
            naive = datetime.strptime(line[16:30], "%Y%m%d%H%M%S")
            off = cur
            if off is None:
                # standard offset of the site zone at that time
                approx = naive.replace(tzinfo=UTC)
                off = std_offset(zone, approx)
            inst = (naive - off).replace(tzinfo=UTC)
            emp = badge if badge.upper().startswith("E") else "E" + badge
            out.append((pid, emp, dr, inst))
    return out


def parse_de_tsv(text, zone):
    out = []
    header = None
    for line in lines_of(text):
        cells = [c.strip() for c in line.split("\t")]
        if "Ausweis" in cells and "Nr" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d, mo, y = r["Datum"].split(".")
        hh, mm = r["Uhrzeit"].split(":")[:2]
        naive = datetime(int(y), int(mo), int(d), int(hh), int(mm))
        z = r.get("Zeitzone", "").upper()
        dst = True if z == "MESZ" else (False if z == "MEZ" else None)
        dr = "IN" if r["Buchung"].upper() == "K" else "OUT"
        out.append((r["Nr"], r["Ausweis"], dr, local_to_instant(naive, zone, dst)))
    return out


def parse_local_csv(text, zone):
    out = []
    rows = csv.DictReader(io.StringIO("\n".join(lines_of(text))))
    for r in rows:
        r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
        if r.get("employee_id") == "employee_id":
            continue
        naive = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
        out.append((r["punch_ref"], r["employee_id"], r["direction"].upper(),
                    local_to_instant(naive, zone, None)))
    return out


def parse_local_jsonl(text, zone):
    out = []
    for line in lines_of(text):
        o = json.loads(line)
        p = o.get("punch") if isinstance(o, dict) else None
        if not p:
            continue
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        out.append((str(p["id"]), str(p["badge"]).strip(), str(p["type"]).upper(),
                    local_to_instant(naive, zone, None)))
    return out


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


# ---------------------------------------------------------------- main
def parse_iso_z(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d.astimezone(UTC)


def round_punch(inst, zone):
    loc = inst.astimezone(zone)
    sec = loc.minute * 60 + loc.second
    r = sec % 360
    delta = (360 - r) if r >= 180 else -r
    return inst + timedelta(seconds=delta)


def main(indir, outfile):
    indir = Path(indir)
    period = json.loads((indir / "period.json").read_text())
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso_z(period["corrections_cutoff"])

    sites = {}
    for r in read_csv_rows(indir / "sites.csv"):
        sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())
    employees = {}
    for r in read_csv_rows(indir / "employees.csv"):
        employees[r["employee_id"].strip()] = r["home_site"].strip()
    rates = {}
    for r in read_csv_rows(indir / "rates.csv"):
        rates.setdefault(r["employee_id"].strip(), []).append(
            (date.fromisoformat(r["effective_from"].strip()), Fraction(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}  # (site, id) -> dict(emp, dir, inst)
    ever = set()
    for site, (zone, fmt) in sorted(sites.items()):
        d = indir / "exports" / site
        if not d.is_dir():
            continue
        files = sorted(p for p in d.rglob("*") if p.is_file())
        for f in files:
            for pid, emp, dr, inst in PARSERS[fmt](read_text(f), zone):
                key = (site, str(pid))
                ever.add(key)
                if key not in punches:
                    punches[key] = {"emp": emp, "dir": dr, "inst": inst}

    # 2. corrections
    corrs = []
    cdir = indir / "corrections"
    if cdir.is_dir():
        for f in sorted(p for p in cdir.rglob("*") if p.is_file()):
            text = read_text(f)
            for r in csv.DictReader(io.StringIO("\n".join(lines_of(text)))):
                r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                if r.get("correction_id") == "correction_id" or not r.get("correction_id"):
                    continue
                corrs.append(r)
    corrs = [(parse_iso_z(r["issued_at"]), r) for r in corrs]
    corrs = [(t, r) for t, r in corrs if t <= cutoff]
    corrs.sort(key=lambda x: (x[0], x[1]["correction_id"]))
    voided = set()
    applied = 0
    for _, r in corrs:
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches and key not in voided:
                voided.add(key)
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches and key not in voided:
                punches[key]["inst"] = parse_iso_z(r["time"])
                applied += 1
        elif act == "add":
            if key not in ever and r["site"] in sites:
                ever.add(key)
                punches[key] = {"emp": r["employee"], "dir": r["type"].upper(),
                                "inst": parse_iso_z(r["time"])}
                applied += 1

    # discard unknown badges
    by_emp = {}
    for (site, pid), p in punches.items():
        if p["emp"] in employees:
            by_emp.setdefault(p["emp"], []).append((p["inst"], 0 if p["dir"] == "OUT" else 1, site, pid, p["dir"]))

    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}
    res = {e: {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0,
               "gross": Fraction(0)} for e in employees}

    def night_minutes(a, b, zone):
        total = 0
        d0 = a.astimezone(zone).date() - timedelta(days=1)
        d1 = b.astimezone(zone).date()
        d = d0
        while d <= d1:
            ws = datetime(d.year, d.month, d.day, 22).replace(tzinfo=zone).astimezone(UTC)
            nd = d + timedelta(days=1)
            we = datetime(nd.year, nd.month, nd.day, 6).replace(tzinfo=zone).astimezone(UTC)
            lo, hi = max(a, ws), min(b, we)
            if hi > lo:
                total += int((hi - lo).total_seconds()) // 60
            d = nd
        return total

    for emp, lst in by_emp.items():
        home = sites[employees[emp]][0] if employees[emp] in sites else UTC
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        last = None
        for inst, _, site, pid, dr in lst:
            rinst = round_punch(inst, sites[site][0])
            wd = rinst.astimezone(home).date()
            if last is not None and last[1] == dr and (inst - last[0]).total_seconds() <= 300:
                if pstart <= wd <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            last = (inst, dr)
            kept.append((rinst, dr, site, wd))
        shifts = []
        pending = None

        def count_open(p):
            if pstart <= p[3] <= pend:
                exc["open_shifts"] += 1

        for p in kept:
            if p[1] == "IN":
                if pending is not None:
                    count_open(pending)
                pending = p
            else:
                if pending is not None:
                    if (p[0] - pending[0]) <= timedelta(hours=16):
                        shifts.append((pending, p))
                        pending = None
                    else:
                        count_open(pending)
                        pending = None
                        if pstart <= p[3] <= pend:
                            exc["orphan_outs"] += 1
                else:
                    if pstart <= p[3] <= pend:
                        exc["orphan_outs"] += 1
        if pending is not None:
            count_open(pending)

        rows = []
        for i, o in shifts:
            wd = i[3]
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, int((o[0] - i[0]).total_seconds()) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(i[0], o[0], sites[i[2]][0]), paid)
            rows.append({"in": i[0], "wd": wd, "paid": paid, "night": night})
        rows.sort(key=lambda r: r["in"])
        daily_used = {}
        for r in rows:
            used = daily_used.get(r["wd"], 0)
            regular_part = max(0, min(r["paid"], 480 - used))
            r["dot"] = r["paid"] - regular_part
            daily_used[r["wd"]] = used + r["paid"]
        week_used = {}
        for r in rows:
            wk = r["wd"] - timedelta(days=r["wd"].weekday())
            base = r["paid"] - r["dot"]
            used = week_used.get(wk, 0)
            reg = max(0, min(base, 2400 - used))
            r["wot"] = base - reg
            week_used[wk] = used + base
        total = Fraction(0)
        ot_sum = 0
        for r in rows:
            ot = r["dot"] + r["wot"]
            regm = r["paid"] - ot
            rl = [x for x in rates.get(emp, []) if x[0] <= r["wd"]]
            rate = rl[-1][1] if rl else Fraction(0)
            total += rate * (regm + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * r["night"] / 60
            ot_sum += ot
        e = res[emp]
        e["shifts"] = len(rows)
        e["paid_minutes"] = sum(r["paid"] for r in rows)
        e["overtime_minutes"] = ot_sum
        e["night_minutes"] = sum(r["night"] for r in rows)
        e["gross"] = total

    def cents(fr):
        c = (fr * 100 + Fraction(1, 2)).__floor__()
        return c

    out_emps = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    totc = 0
    for emp in sorted(employees):
        e = res[emp]
        c = cents(e["gross"])
        totc += c
        out_emps[emp] = {"shifts": e["shifts"], "paid_minutes": e["paid_minutes"],
                         "overtime_minutes": e["overtime_minutes"],
                         "night_minutes": e["night_minutes"], "gross": "%d.%02d" % (c // 100, c % 100)}
        for k in tot:
            tot[k] += e[k]
    tot["gross"] = "%d.%02d" % (totc // 100, totc % 100)
    result = {"period": {"start": period["start"], "end": period["end"]},
              "employees": out_emps, "exceptions": exc, "totals": tot}
    Path(outfile).parent.mkdir(parents=True, exist_ok=True)
    Path(outfile).write_text(json.dumps(result, indent=1))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
